"""Checks for Part B. Do not edit this file — your instructor grades with
an original copy, so changing it will not change your grade."""

import builtins

from part_b_loops import (
    largest,
    remove_duplicates,
    reverse_words,
    sum_of_evens,
    word_count,
)


def test_b1_sum_of_evens():
    assert sum_of_evens([1, 2, 3, 4, 10]) == 16
    assert sum_of_evens([1, 3, 5]) == 0, "No even numbers → 0"
    assert sum_of_evens([]) == 0, "Empty list → 0"
    assert sum_of_evens([-2, -4, 1]) == -6, "Negative even numbers count too"


def test_b2_largest(monkeypatch):
    def no_max(*args, **kwargs):
        raise AssertionError("largest() must not use max() — use a loop instead")

    # Block max() only while the student's function runs.
    with monkeypatch.context() as m:
        m.setattr(builtins, "max", no_max)
        results = [largest([3, 9, 2]), largest([-5, -2, -8]), largest([7]), largest([])]

    assert results[0] == 9, "largest([3, 9, 2]) should be 9"
    assert results[1] == -2, "Works with all-negative lists"
    assert results[2] == 7, "A single-item list returns that item"
    assert results[3] is None, "Empty list → None"


def test_b3_reverse_words():
    assert reverse_words("python is fun") == "fun is python"
    assert reverse_words("hello") == "hello"
    assert reverse_words("one two three four") == "four three two one"


def test_b4_word_count():
    assert word_count("the cat and the hat") == {"the": 2, "cat": 1, "and": 1, "hat": 1}
    assert word_count("Go go GO") == {"go": 3}, "Words should be counted as lowercase"
    assert word_count("") == {}, "Empty text → empty dictionary"


def test_b5_remove_duplicates():
    original = [3, 1, 3, 2, 1]
    assert remove_duplicates(original) == [3, 1, 2], "Keep first occurrences, in order"
    assert original == [3, 1, 3, 2, 1], "Don't change the original list — return a new one"
    assert remove_duplicates(["a", "b", "a"]) == ["a", "b"]
    assert remove_duplicates([]) == []
